<script setup lang="ts">
import {Head,useForm,router}from'@inertiajs/vue3';import{ref}from'vue';
const p=defineProps<{channels:any[];customers:any[]}>();const search=ref('');const found=ref<any[]>([]);const message=ref('');const quote=ref<any>(null);
const f=useForm<any>({reference:'',channel_id:'',customer_id:'',ordered_on:new Date().toISOString().slice(0,10),delivery_charge:'0',operation_key:crypto.randomUUID(),lines:[]});
const csrf=()=>document.querySelector<HTMLMetaElement>('meta[name=csrf-token]')?.content??'';
async function lookup(barcode=false){message.value='';const response=await fetch('/catalog/search?'+new URLSearchParams({[barcode?'barcode':'q']:search.value}),{headers:{Accept:'application/json'}});const data=await response.json();found.value=data.products??[];if(barcode&&found.value.length===1){add(found.value[0]);search.value='';found.value=[];}else if(!found.value.length)message.value='Produkti nuk u gjet.';}
function plusOne(s:string){const [a,b='']=s.split('.');const value=BigInt(a)*1000000n+BigInt(b.padEnd(6,'0'))+1000000n;return `${value/1000000n}.${String(value%1000000n).padStart(6,'0')}`;}
function add(product:any){const old=f.lines.find((l:any)=>l.product_id===product.id);if(old)old.quantity=plusOne(old.quantity);else f.lines.push({product_id:product.id,name:product.name,sku:product.sku,quantity:'1',unit_price:product.selling_price,discount:'0'});calculate();}
async function calculate(){if(!f.lines.length){quote.value=null;return;}const response=await fetch('/sales/quote',{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':csrf()},body:JSON.stringify(f.data())});const data=await response.json();if(response.ok){quote.value=data.quote;message.value='';}else{quote.value=null;message.value=data.message??'Kontrolloni të dhënat.';}}
function create(){f.post('/sales',{onSuccess:()=>router.visit('/sales'),preserveScroll:true});}
</script>
<template><Head title="POS"/><div class="tp-page-heading"><div><div class="tp-eyebrow">SHITJE NGA NJË STOK QENDROR</div><h1>Shitje / POS</h1><p>Skanoni barkodin ose kërkoni produktin. Konfirmimi fiskal ndiqet para dërgimit.</p></div></div><div class="tp-dashboard-grid"><section class="tp-panel"><form class="tp-table-toolbar" @submit.prevent="lookup(true)"><input v-model="search" autofocus placeholder="Skanoni barkodin…" aria-label="Barkodi"/><button class="tp-button">Shto me barkod</button><button type="button" class="tp-button secondary" @click="lookup(false)">Kërko</button></form><button v-for="product in found" :key="product.id" class="tp-button secondary mr-2 mb-2" @click="add(product)">{{product.sku}} · {{product.name}}</button><div class="tp-table-wrap"><table><thead><tr><th>Produkti</th><th>Sasia</th><th>Çmimi pa TVSH</th><th></th></tr></thead><tbody><tr v-for="(line,i) in f.lines" :key="line.product_id"><td>{{line.name}}<small class="block tp-muted">{{line.sku}}</small></td><td><input v-model="line.quantity" inputmode="decimal" class="w-20 border rounded p-2" @change="calculate"/></td><td>{{line.unit_price}}</td><td><button class="tp-text-btn danger" @click="f.lines.splice(i,1);calculate()">Hiq</button></td></tr></tbody></table></div><div v-if="!f.lines.length" class="tp-empty"><h3>Shporta është bosh</h3><p>Shtoni produktin e parë.</p></div></section><section class="tp-panel"><form @submit.prevent="create"><div class="tp-fields"><label class="tp-field wide"><span>Referenca e porosisë</span><input v-model="f.reference" required/></label><label class="tp-field wide"><span>Kanali</span><select v-model="f.channel_id" required><option value="">Zgjidhni…</option><option v-for="c in channels" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label class="tp-field wide"><span>Klienti (opsional)</span><select v-model="f.customer_id"><option value="">Pa klient të emërtuar</option><option v-for="c in customers" :key="c.id" :value="c.id">{{c.name}}</option></select></label></div><div v-if="quote" class="tp-notice"><p>Pa TVSH: {{quote.net}} EUR</p><p>TVSH: {{quote.tax}} EUR</p><strong>Gjithsej: {{quote.gross}} EUR</strong></div><p v-if="message" class="tp-error">{{message}}</p><p v-for="(e,k) in f.errors" :key="k" class="tp-error">{{e}}</p><button class="tp-button w-full mt-5" :disabled="f.processing||!quote">Krijo porosinë dhe rezervo stokun</button><p class="tp-muted mt-4">Porosia nuk është pagesë ose kupon fiskal. Përfundoni veprimet në detajet e porosisë.</p></form></section></div></template>
